mapper.select:
/* AppAdminSiteOpsMapper.existsAccessibleSite */
SELECT EXISTS(
    SELECT 1
      FROM TB_USER_SITE_AUTH USA
      INNER JOIN TB_SITE S
        ON S.CMPNY_CD = USA.CMPNY_CD
       AND S.SITE_CD  = USA.SITE_CD
     WHERE USA.CMPNY_CD = #{cmpnyCd}
       AND USA.USER_CD  = #{userCd}
       AND USA.SITE_CD  = #{siteCd}
       AND USA.USE_YN   = 'Y'
       AND S.USE_YN     = 'Y'
)

/* AppAdminSiteOpsMapper.countValidDailyUser */
SELECT COUNT(1)
  FROM TB_DAILY_USER DU
 WHERE DU.CMPNY_CD = #{cmpnyCd}
   AND DU.SITE_CD  = #{siteCd}
   AND DU.USER_CD  = #{userCd}
   AND DU.USE_YN   = 'Y'
   AND DU.ACCOUNT_STATUS = '01'
   AND DU.WITHDRAWAL_DATE IS NULL
   AND DU.WORK_EXPIRE_DATE >= DATE_FORMAT(NOW(), '%Y%m%d')

/* AppAdminSiteOpsMapper.countOccupiedSlot */
SELECT EXISTS(
    SELECT 1
      FROM TB_DAILY_USER_SLOT DS
     WHERE DS.CMPNY_CD     = #{cmpnyCd}
       AND DS.SITE_CD      = #{siteCd}
       AND DS.CURR_USER_CD = #{userCd}
       AND DS.SLOT_STATUS  = '02'
       AND DS.USE_YN       = 'Y'
)

/* AppAdminSiteOpsMapper.selectDailyUserNm */
SELECT DU.USER_NM AS userNm
  FROM TB_DAILY_USER DU
 WHERE DU.CMPNY_CD = #{cmpnyCd}
   AND DU.SITE_CD  = #{siteCd}
   AND DU.USER_CD  = #{userCd}
 LIMIT 1

/* AppAdminSiteOpsMapper.lockDailyUserForCheckIn */
SELECT DU.USER_CD
  FROM TB_DAILY_USER DU
 WHERE DU.CMPNY_CD = #{cmpnyCd}
   AND DU.SITE_CD  = #{siteCd}
   AND DU.USER_CD  = #{userCd}
 FOR UPDATE

/* AppAdminSiteOpsMapper.countAttdToday */
SELECT COUNT(*)
  FROM TB_USER_ATTD_MGMT A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.SITE_CD  = #{siteCd}
   AND A.USER_CD  = #{userCd}
   AND A.WORK_YMD = #{todayYmd}
   AND A.DEL_YN   = 'N'
   AND A.CHECK_IN_TIME IS NOT NULL

/* AppAdminSiteOpsMapper.countOpenAttdToday */
SELECT COUNT(*)
  FROM TB_USER_ATTD_MGMT A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.SITE_CD  = #{siteCd}
   AND A.USER_CD  = #{userCd}
   AND A.WORK_YMD = #{todayYmd}
   AND A.DEL_YN   = 'N'
   AND A.CHECK_IN_TIME IS NOT NULL
   AND A.CHECK_OUT_TIME IS NULL

/* AppAdminSiteOpsMapper.selectOpenAttdToday */
SELECT A.ATTD_ID  AS attdId
     , A.WORK_YMD AS workYmd
  FROM TB_USER_ATTD_MGMT A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.SITE_CD  = #{siteCd}
   AND A.USER_CD  = #{userCd}
   AND A.WORK_YMD = #{todayYmd}
   AND A.DEL_YN   = 'N'
   AND A.CHECK_IN_TIME IS NOT NULL
   AND A.CHECK_OUT_TIME IS NULL
 ORDER BY A.WORK_SEQ DESC, A.ATTD_ID DESC
 LIMIT 1

