/* AppAdminSiteOpsMapper.insertDailyCheckIn */
INSERT INTO TB_USER_ATTD_MGMT (
      ATTD_ID
    , CMPNY_CD
    , SITE_CD
    , USER_CD
    , WORK_YMD
    , NODE_CD
    , WORK_SEQ
    , CHECK_IN_DATE
    , CHECK_IN_TIME
    , CHECK_IN_METHOD
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{c.attdId}
    , #{c.cmpnyCd}
    , #{c.siteCd}
    , #{c.userCd}
    , #{c.workYmd}
    , NULL
    , #{c.workSeq}
    , #{c.checkInDate}
    , #{c.checkInTime}
    , #{c.checkInMethod}
    , 'N'
    , #{c.insertNo}
    , NOW()
)

mapper.update:
/* AppAdminSiteOpsMapper.updateDailyCheckOut */
UPDATE TB_USER_ATTD_MGMT
   SET
         CHECK_OUT_DATE   = #{c.checkOutDate}
       , CHECK_OUT_TIME   = #{c.checkOutTime}
       , CHECK_OUT_METHOD = #{c.checkOutMethod}
       , UPDATE_NO        = #{c.userCd}
       , UPDATE_DATE      = NOW()
 WHERE ATTD_ID  = #{c.attdId}
   AND CMPNY_CD = #{c.cmpnyCd}
   AND DEL_YN   = 'N'
   AND CHECK_OUT_TIME IS NULL
